    [3310001] = {
        id = 3310001,
        text = "1.追獵計畫在社團等級4級時開啟，加入社團時間超過48小時且社團基礎貢獻度到達200的成員可參與此活動",
        minipack = 0,
    },
    [3310003] = {
        id = 3310003,
        text = "3.備戰階段中，社團成員單人挑戰社團Boss的3個弱點副本，每天有2次挑戰次數，次日淩晨6點重置（3個副本共用次數）",
        minipack = 0,
    },
    [3310005] = {
        id = 3310005,
        text = "5.挑戰階段中，社團成員共同組隊挑戰社團Boss。社團Boss共有40等級（一個等級即為一輪），每成功擊敗一級Boss，會繼續刷出下一級。下一週期初始挑戰Boss等級由上一週期成功挑戰最高Boss等級決定（向下調整5級）",
        minipack = 0,
    },
    [471106] = {
        id = 471106,
        text = "#的信仰值消耗-2",
        minipack = 0,
    },
    [3310009] = {
        id = 3310009,
        text = "9.作戰獎勵分為Boss首通獎勵和擊殺獎勵。首次擊殺Boss可以拿到首通獎勵，在下一週期備戰階段開啟前均可領取，未領取的首通獎勵不會補發；本週期結束後會對社團挑戰Boss等級進行結算，社團成員可以獲得最高等級Boss及向下2級內的Boss擊殺獎勵，在下一週期挑戰階段開啟前均可領取，未領取的擊殺獎勵不會補發",
        minipack = 0,
    },
    [3310011] = {
        id = 3310011,
        text = "11.社團榮譽與社團競賽排名關聯，為一些活動限定獎勵，作為後期規劃內容，敬請期待",
        minipack = 0,
    },
    [3310013] = {
        id = 3310013,
        text = "13.傷害占比獎勵結算要統計最終的個人傷害和社團成員造成的總傷害，所以領取獎勵時間會稍微晚一些，從下週一早上8點開始，在下一週期挑戰階段開啟前均可領取，未領取的個人傷害占比獎勵不會補發",
        minipack = 0,
    },
