    [2081366] = {
        id = 2081366,
        text = "豆沙粽子",
        minipack = 0,
    },
    [2081367] = {
        id = 2081367,
        text = "學校料理課上做出來的粽子，粒粒精選，五穀清香。是十香和折紙的心意哦。",
        minipack = 0,
    },
    [2081368] = {
        id = 2081368,
        text = "狂三和萬由里親自選料製作的肉粽，美味多汁。",
        minipack = 0,
    },
    [2081369] = {
        id = 2081369,
        text = "甜蜜又經典的口味。是琴里親自做的餡料、美九幫忙包好的哦。",
        minipack = 0,
    },
    [2081370] = {
