    [2081376] = {
        id = 2081376,
        text = "紅棗[活動]",
        minipack = 0,
    },
    [2081377] = {
        id = 2081377,
        text = "傳說端午節是妖怪出沒的日子，而用糯米可以祛除邪氣。當然它也是製作粽子必不可少的材料。",
        minipack = 0,
    },
    [2081378] = {
        id = 2081378,
        text = "飽滿的玉米粒有著甜爽的味道，如果加在端午節粽子裡，口感會越發讓人感到幸福。",
        minipack = 0,
    },
    [2081379] = {
        id = 2081379,
        text = "小小的花生中包含著能量，可以讓粽香飄得更遠。",
        minipack = 0,
    },
    [2081380] = {
        id = 2081380,
        text = "燥熱難耐的端午節，不吃肉怎麼行？六分精肉四分肥肉，粽子就會像是中了魔法般可口。",
        minipack = 0,
    },
    [2081381] = {
        id = 2081381,
        text = "萃取蛋黃加入粽子，不僅提升了粽子的口感，金黃的顏色也讓人垂涎。",
        minipack = 0,
    },
    [2081382] = {
        id = 2081382,
        text = "甜粽中總會加入一撮紅豆沙，口感粗糙中有細膩，香味十分濃郁。",
        minipack = 0,
    },
    [2081383] = {
        id = 2081383,
        text = "紅棗能夠保健人們的脾胃，酸酸甜甜的味道也是無法代替的盛夏回憶。",
        minipack = 0,
