    [13311419] = {
        id = 13311419,
        text = "【秘寶碎片】\n由遠古先祖的牙齒磨制而成，庇佑著根達亞子民。\n(戰鬥中，每次傷害有幾率提升場上友軍精靈移速、攻擊）",
        minipack = 0,
    },
    [13311427] = {
        id = 13311427,
        text = "【秘寶碎片】\n黃金鹹魚是鹹黨派系的至寶，而甜黨貓族也有執著的信仰。\n(戰鬥中，可在瀕死時復活,恢復一定生命值）",
        minipack = 0,
    },
    [13311435] = {
        id = 13311435,
        text = "打開後可在領結潮流碎片*1，鋼鐵甜甜圈碎片*1，文明之匙碎片*1，海洋故鄉碎片*1，喚潮的螺號碎片*1中任選一種。",
        minipack = 0,
    },
    [13311507] = {
