    [910026] = {
        id = 910026,
        text = "不想吃就是最好的理由！即使是司令官，妹妹也需要耐心安慰！",
        minipack = 0,
    },
    [910027] = {
        id = 910027,
        text = "挑食的孩子長不高！",
