    [63056] = {
        id = 63056,
        text = "1.在質點預設中誓約者們可以保存精靈當前裝備的質點作為預設方案。\n       2.誓約者們可以將預設中的方案應用到任意精靈上。\n       3.每個誓約者保存的質點方案最多為20套。",
        minipack = 0,
    },
    [2200420] = {
        id = 2200420,
        text = "連續閃現到目標附近，向目標開槍發起數次攻擊。到5次。技能總共可造成狂三攻擊力540%的黑暗傷害。",
        minipack = 0,
