    [1701491] = {
        id = 1701491,
        text = "這才對，你就好好期待一番吧！",
        minipack = 0,
    },
    [1701492] = {
        id = 1701492,
        text = "是嘛……咳咳，無妨，去為你的信仰獻身吧。",
