    [1701493] = {
        id = 1701493,
        text = "沒問題，我對服裝還是很瞭解的！",
        minipack = 0,
    },
    [1701494] = {
        id = 1701494,
        text = "來，你隨意稱讚我好了！（古風格、中二的口氣）",
        minipack = 0,
    },
    [1701495] = {
        id = 1701495,
        text = "這件！與漆黑之槍如此般配，實在是太美妙了！",
