    [1701496] = {
        id = 1701496,
        text = "眷屬喲，所謂何事？",
        minipack = 0,
    },
    [1701497] = {
        id = 1701497,
        text = "呐……不說點什麼嗎？……不要搞得這麼尷尬啦。",
        minipack = 0,
    },
    [1701498] = {
        id = 1701498,
        text = "嗯，你準備了供品，考慮得真周到。（古風格、中二的口氣）……哇，這是什麼呀，超好吃呢！（年輕人的口氣）",
        minipack = 0,
    },
    [1701499] = {
