        text = "咳咳，不錯的貢品，汝做的不錯",
        minipack = 0,
    },
    [1701502] = {
        id = 1701502,
        text = "哼哼，我有累積了“業（Karma）”……（古風格、中二的口氣）欸？不用這樣的？是什麼意思啊！（年輕人的口氣）",
        minipack = 0,
    },
    [1701503] = {
