    },
    [1701504] = {
        id = 1701504,
        text = "說不定下一次能贏過夕弦呢！",
        minipack = 0,
    },
    [1701505] = {
        id = 1701505,
        text = "咳咳，好吧，和你聊一會兒吧。你應該感到光榮。（注釋：古風格、中二的口氣）",
        minipack = 0,
    },
    [1701506] = {
        id = 1701506,
        text = "風之化身八舞耶俱矢，在此降臨！（古風格、中二的口氣）",
        minipack = 0,
    },
    [1701507] = {
        id = 1701507,
        text = "咳咳咳！已經沒人能阻擋我了！（古風格、中二的口氣）",
        minipack = 0,
    },
    [1701508] = {
