    [1701560] = {
        id = 1701560,
        text = "最喜歡darling了~",
        minipack = 0,
    },
    [1701561] = {
        id = 1701561,
        text = "心急吃不了熱豆腐哦，Darling",
        minipack = 0,
    },
    [1701562] = {
        id = 1701562,
        text = "今天的“演唱會”也很順利呢。",
        minipack = 0,
    },
    [1701563] = {
        id = 1701563,
        text = "要我打電話提醒你嗎？Darling千萬不要遲到哦。",
        minipack = 0,
    },
    [1701564] = {
        id = 1701564,
        text = "為什麼?不想聽我唱歌了嗎？（委屈，哭腔）",
        minipack = 0,
    },
    [1701565] = {
        id = 1701565,
        text = "想看我穿新的演出服嗎？",
        minipack = 0,
    },
    [1701566] = {
        id = 1701566,
        text = "反應很棒呢！是被我迷住了嗎？",
        minipack = 0,
    },
    [1701567] = {
        id = 1701567,
        text = "Darling快看，這件新演出服怎麼樣？",
        minipack = 0,
    },
    [1701568] = {
        id = 1701568,
        text = "Darling要送我什麼禮物嗎？真是太高興了！",
        minipack = 0,
    },
    [1701569] = {
        id = 1701569,
        text = "Darling有什麼禮物要給我嗎？超期待哦。",
        minipack = 0,
    },
    [1701570] = {
        id = 1701570,
        text = "嗯！好好吃！Darling的愛心在裡面呢！",
        minipack = 0,
    },
    [1701571] = {
        id = 1701571,
        text = "啊啦~，看起來好好吃。我可以收嗎？",
        minipack = 0,
    },
    [1701572] = {
        id = 1701572,
        text = "哇~~！謝謝你~！作為回禮我給你抱一下~！",
        minipack = 0,
    },
    [1701573] = {
        id = 1701573,
        text = "謝謝你~ 我會好好保存的~~！",
        minipack = 0,
    },
    [1701574] = {
        id = 1701574,
        text = "Darling，太喜歡你了！",
        minipack = 0,
    },
    [1701575] = {
        id = 1701575,
        text = "啦啦啦，Darling想聽我唱歌了嗎？",
        minipack = 0,
    },
    [1701576] = {
        id = 1701576,
        text = "我是認真的哦，竟然打攪我和darling約會，真是討厭，哼~",
        minipack = 0,
    },
    [1701577] = {
        id = 1701577,
        text = "我說，一直盯著人家看是不會要到簽名的哦",
        minipack = 0,
    },
    [1701578] = {
        id = 1701578,
        text = "嗨~多謝你的指名，darling。我是你的美九哦~！",
        minipack = 0,
    },
    [1701579] = {
        id = 1701579,
        text = "能唱出更美妙的歌聲了~！",
        minipack = 0,
    },
    [1701580] = {
        id = 1701580,
        text = "雖然戰鬥很不適合淑女，不過為了darling，什麼都可以哦。",
        minipack = 0,
    },
    [1701581] = {
        id = 1701581,
        text = "darling~就讓我來保護你吧！",
        minipack = 0,
    },
    [1701582] = {
        id = 1701582,
        text = "就像做夢一樣。我也像大家一樣，能和你一起約會了",
        minipack = 0,
    },
    [1701583] = {
        id = 1701583,
        text = "嘿嘿，沒想到會這麼開心呢。",
        minipack = 0,
    },
    [1701584] = {
        id = 1701584,
        text = "啊啦，被你發現了呢，嘻嘻。",
        minipack = 0,
    },
    [1701585] = {
        id = 1701585,
        text = "不管來多少次，都覺得這裡很不錯呢。",
        minipack = 0,
    },
    [1701586] = {
        id = 1701586,
        text = "不要著急，慢慢來。",
        minipack = 0,
    },
    [1701587] = {
        id = 1701587,
        text = "那就待會兒見，我會很期待的。",
        minipack = 0,
    },
    [1701588] = {
        id = 1701588,
        text = "沒關係，下次再加油。",
        minipack = 0,
    },
    [1701589] = {
        id = 1701589,
        text = "服裝店？有很多有趣的回憶呢，嘻嘻。",
        minipack = 0,
    },
    [1701590] = {
        id = 1701590,
        text = "合適嗎？……嘿嘿，你喜歡就好",
        minipack = 0,
    },
    [1701591] = {
        id = 1701591,
        text = "這件衣服，真漂亮呢。更喜歡我了嗎？",
        minipack = 0,
    },
    [1701592] = {
        id = 1701592,
        text = "嗯？悄悄地跑來找我嗎？嘻嘻~",
        minipack = 0,
    },
    [1701593] = {
        id = 1701593,
        text = "呐，是要送我禮物嗎？",
        minipack = 0,
    },
    [1701594] = {
        id = 1701594,
        text = "這個……，從來沒有嘗試過的味道",
        minipack = 0,
    },
    [1701595] = {
        id = 1701595,
        text = "謝謝你，的確很美味",
        minipack = 0,
    },
    [1701596] = {
        id = 1701596,
        text = "好開心，原來你一直都知道，我所喜歡的",
        minipack = 0,
    },
    [1701597] = {
        id = 1701597,
        text = "真的嗎？真的是給我的嗎？",
        minipack = 0,
    },
    [1701598] = {
        id = 1701598,
        text = "我一如既往，深深地愛著你。……開玩笑了",
        minipack = 0,
    },
    [1701599] = {
        id = 1701599,
        text = "想我了嗎？沒關係，我在這裡哦。",
        minipack = 0,
    },
    [1701600] = {
        id = 1701600,
        text = "能感受到，大家的力量呢。",
        minipack = 0,
    },
    [1701601] = {
        id = 1701601,
        text = "？有什麼事嗎？",
        minipack = 0,
    },
    [1701602] = {
        id = 1701602,
        text = "我是裁定者。我要——看清你。",
        minipack = 0,
    },
    [1701603] = {
        id = 1701603,
        text = "這樣……就能保護你了",
        minipack = 0,
    },
    [1701604] = {
        id = 1701604,
        text = "和大家相比，我還差得很遠吧。",
        minipack = 0,
    },
    [1701605] = {
        id = 1701605,
        text = "為了所愛之人，我會全力以赴。",
        minipack = 0,
