    },
    [1701991] = {
        id = 1701991,
        text = "哈，約會……？和我？你認真的？",
        minipack = 0,
    },
    [1701992] = {
        id = 1701992,
        text = "今天要做什麼呀？",
        minipack = 0,
    },
    [1701993] = {
        id = 1701993,
        text = "你不挺厲害的嘛……",
        minipack = 0,
    },
    [1701994] = {
        id = 1701994,
        text = "約會……好像很開心的樣子……不沒什麼。",
        minipack = 0,
    },
    [1701995] = {
        id = 1701995,
        text = "什麼嘛……",
        minipack = 0,
    },
    [1701996] = {
        id = 1701996,
        text = "要拒絕的話就趁現在哦，真的可以嗎？",
        minipack = 0,
    },
    [1701997] = {
        id = 1701997,
        text = "啊好好，我想也是。一點都沒失落哦，這不是理所當然的麼。",
        minipack = 0,
    },
    [1701998] = {
        id = 1701998,
        text = "我說，也沒什麼好看的吧。",
        minipack = 0,
    },
    [1701999] = {
        id = 1701999,
        text = "所以說別給我送衣服啦……",
        minipack = 0,
    },
    [1702000] = {
        id = 1702000,
        text = "謝謝你……我穿……好看嗎？",
        minipack = 0,
    },
    [1702001] = {
        id = 1702001,
        text = "什麼啊那是。哈？禮物？給我的？",
        minipack = 0,
    },
    [1702002] = {
        id = 1702002,
        text = "要停手的話就趁現在哦，給其他女孩不更好麼……",
        minipack = 0,
    },
    [1702003] = {
        id = 1702003,
        text = "嗚哇，真好吃，這是啥……謝，謝謝……",
        minipack = 0,
    },
    [1702004] = {
        id = 1702004,
        text = "一般吧。",
        minipack = 0,
    },
    [1702005] = {
        id = 1702005,
        text = "哈，好厲害……",
        minipack = 0,
    },
    [1702006] = {
        id = 1702006,
        text = "哼，嘛，還行吧。",
        minipack = 0,
    },
    [1702007] = {
        id = 1702007,
        text = "……不，嘛，也不壞不是麼。",
        minipack = 0,
    },
    [1702008] = {
        id = 1702008,
        text = "我真的可以麼？",
        minipack = 0,
    },
    [1702009] = {
        id = 1702009,
        text = "什麼？！有趣的遊戲要開始了嗎？",
        minipack = 0,
    },
    [1702010] = {
        id = 1702010,
        text = "什麼事啊？磨磨唧唧的真是麻煩。",
        minipack = 0,
    },
    [1702011] = {
        id = 1702011,
        text = "我要把你的人生給毀掉！",
        minipack = 0,
