    [1702053] = {
        id = 1702053,
        text = "[主線]七罪_chapter 1",
        minipack = 0,
    },
    [1702054] = {
        id = 1702054,
        text = "擁有墨色如同黑夜般長髮的少女，明亮的雙眸是夜空最閃亮的星星。",
        minipack = 0,
    },
    [1702055] = {
        id = 1702055,
        text = "即使擁有著強大戰士的身份，也無法遮蓋她的少女心。",
        minipack = 0,
    },
    [1702056] = {
        id = 1702056,
        text = "內心如玻璃般脆弱，害怕陌生人的她，總是需要你的呵護。",
        minipack = 0,
    },
    [1702057] = {
        id = 1702057,
        text = "強大而殘酷的力量，以及更加致命的美貌。",
        minipack = 0,
    },
    [1702058] = {
        id = 1702058,
        text = "她試圖讓自己永遠保持冷靜，卻總是迷失在哥哥的溫情中。",
        minipack = 0,
    },
    [1702059] = {
        id = 1702059,
        text = "「愛」是她存在的唯一理由，就像天使般高高在上。",
        minipack = 0,
    },
    [1702060] = {
        id = 1702060,
        text = "只有在值得信賴的人面前，才會露出本來面目。",
        minipack = 0,
    },
    [1702061] = {
        id = 1702061,
        text = "七夕節嗎？唔姆……對我來說只要能和你約會，那就是個好日子。\n和我在一起你也很快樂，對嗎？",
        minipack = 0,
    },
    [1702062] = {
        id = 1702062,
        text = "親愛的戀人，希望你今天能接受我的鮮花和情書。\n來吧，和我一起共度良宵！",
        minipack = 0,
    },
    [1702063] = {
        id = 1702063,
        text = "四糸乃已經比以前堅強了許多……\n七…七夕…節快樂~",
        minipack = 0,
    },
    [1702064] = {
        id = 1702064,
        text = "啊啦，雖然是命中註定的相遇，但我偶爾也會覺得幸運呢～\n能在時間的長河裡等到你。",
        minipack = 0,
    },
    [1702065] = {
        id = 1702065,
        text = "笨蛋哥哥，雖然這是屬於情侣們的節日，但我也有話想對你說。\n一直以來，感謝有你相伴。",
        minipack = 0,
    },
    [1702066] = {
        id = 1702066,
        text = "今天我要更常牽你的手，走在鮮花盛開的原野，或者落英繽紛的樹下。\n直到夕陽餘暉將我們的影子拉長。",
        minipack = 0,
    },
    [1702067] = {
        id = 1702067,
        text = "其實我偶爾也想對你敞開心扉……\n只是在等待最美好的時刻。",
        minipack = 0,
    },
