    [1702396] = {
        id = 1702396,
        text = "是否還原本次的所有修改？",
        minipack = 0,
    },
    [1702397] = {
        id = 1702397,
        text = "媽媽，這裡有個奇怪的大叔！",
        minipack = 0,
    },
    [1702398] = {
        id = 1702398,
        text = "嘖，變小後的身體真是不方便……",
        minipack = 0,
    },
    [1702399] = {
        id = 1702399,
        text = "我想去衛生間，不能自己去。",
        minipack = 0,
    },
    [1702400] = {
        id = 1702400,
        text = "我要吃餅乾，喂我吧。",
        minipack = 0,
    },
    [1702401] = {
        id = 1702401,
        text = "我名叫千代紙，請多指教。",
        minipack = 0,
    },
    [1702402] = {
        id = 1702402,
        text = "我是父母愛情的結晶。",
        minipack = 0,
    },
    [1702403] = {
        id = 1702403,
        text = "爸爸，請不要做奇怪的事。",
        minipack = 0,
    },
    [1702404] = {
        id = 1702404,
        text = "三年級A班",
        minipack = 0,
    },
    [1702405] = {
        id = 1702405,
        text = "五河千代紙",
        minipack = 0,
    },
    [1702406] = {
        id = 1702406,
        text = "就算是緊湊的裝修風格，也需要寬敞的玄關設計，因為這是對客人的禮儀，玄關偶爾也會成為和精靈們發生“特別互動”的場所哦！~",
        minipack = 0,
    },
    [1702407] = {
        id = 1702407,
        text = "",
        minipack = 0,
    },
    [1702408] = {
        id = 1702408,
        text = "",
        minipack = 0,
    },
    [1702409] = {
        id = 1702409,
        text = "",
        minipack = 0,
    },
    [1702410] = {
        id = 1702410,
        text = "",
        minipack = 0,
    },
    [1702411] = {
        id = 1702411,
        text = "是普通的住宅呢。這個角度不錯。",
        minipack = 0,
    },
    [1702412] = {
        id = 1702412,
        text = "",
        minipack = 0,
