    [1702414] = {
        id = 1702414,
        text = "",
        minipack = 0,
    },
    [1702415] = {
        id = 1702415,
        text = "",
        minipack = 0,
    },
    [1702416] = {
        id = 1702416,
        text = "建造精靈公寓的時候，琴里打算讓每個精靈都居住在粉色的世界裡，就算是高傲如狂三，偶爾也會有少女的一面吧？（雖然狂三不住在這裡^0^）",
        minipack = 0,
    },
    [1702417] = {
        id = 1702417,
        text = "想要捕捉精靈們的日常生活，就到精靈公寓的客廳多轉轉吧，不拘小節的精靈們，也許會給你一些特殊福利哦~",
        minipack = 0,
    },
    [1702418] = {
        id = 1702418,
        text = "夜晚的精靈公寓房間，是精靈們安睡的地方，這裡可以俯瞰大半個天宮市的夜景，但願能帶給她們一個浪漫的夢境。",
        minipack = 0,
    },
    [1702419] = {
        id = 1702419,
        text = "夜晚的精靈公寓客廳，如果電視機發出柔和的冷光，你一定會聽到四糸奈的吵嚷、七罪的尖叫，因為晚間劇正在播放。",
        minipack = 0,
    },
    [1702420] = {
        id = 1702420,
        text = "",
        minipack = 0,
    },
    [1702421] = {
        id = 1702421,
        text = "",
        minipack = 0,
    },
    [1702422] = {
        id = 1702422,
        text = "即使明媚的陽光，也不能照亮精靈們壓抑的心情，我堂堂精靈大人，為什麼要乖乖坐在這裡聽講啊？真是讓人頭大。",
        minipack = 0,
    },
    [1702423] = {
        id = 1702423,
        text = "空空蕩蕩的屋頂，偶爾也會吸引偷懶的學生過來聚會，據說有人曾經在屋頂上見到過神秘的紅衣少女，那美麗的臉龐讓人難忘。",
        minipack = 0,
    },
    [1702424] = {
        id = 1702424,
        text = "會讓某些人想起罰站經歷的教室走廊，一到下課時間這裡就會變得非常熱鬧，美好的時光也從這裡悄悄消逝……",
        minipack = 0,
    },
    [221001] = {
        id = 221001,
        text = "約會資料不存在",
        minipack = 0,
    },
    [1702426] = {
        id = 1702426,
        text = "據說這裡是最佳觀賞月亮的地方，不過晚上很少會有人了來天臺吧？如果偶然看到一個孤獨的少女背影，也請不要太驚訝。",
        minipack = 0,
    },
    [1702427] = {
        id = 1702427,
        text = "夜晚的學校走廊是個安靜的去處，不過看起來不大適合約會的樣子，也許只有特別的精靈，才會想要到這種僻靜的地方來吧？",
        minipack = 0,
