    [1702462] = {
        id = 1702462,
        text = "被精心裝點後，非常具有文藝氣息的花店。女孩子都喜歡這不同的花朵，看似一覽無餘的花店，可是包含著約會的最高學問哦~",
        minipack = 0,
    },
    [1702463] = {
        id = 1702463,
        text = "常常因為攻略精靈而累到脫力的話，一定要常來飲品店坐坐，一杯冰巧克力，不僅會讓精靈的心情好起來，你的體力槽也會快速恢復哦~",
        minipack = 0,
    },
    [1702464] = {
        id = 1702464,
        text = "因為有著芬芳的花朵，夜晚的花店常常有蝴蝶光顧。燈光下絢爛的花兒們，一定會為約會帶來不一樣的溫馨體驗。",
        minipack = 0,
