        minipack = 0,
    },
    [1702643] = {
        id = 1702643,
        text = "「要先吃飯嗎？還是先洗澡？還是說要先——」洗、洗澡水已經……放好了……",
        minipack = 0,
    },
    [1702644] = {
        id = 1702644,
        text = "四糸奈……唔……Zzzz",
        minipack = 0,
    },
    [1702645] = {
        id = 1702645,
        text = "貴安哦，有好好吃早餐嗎？",
        minipack = 0,
    },
    [1702646] = {
        id = 1702646,
        text = "啊啦……又見面了。嗯呵呵，是不是命運呢？",
        minipack = 0,
    },
    [1702647] = {
        id = 1702647,
        text = "時間過得可真快啊，要好好收集起來才行呢。",
        minipack = 0,
    },
    [1702648] = {
        id = 1702648,
        text = "給我起來。不快點起來的話，我就把你以前寫的小說發到SNS上。",
        minipack = 0,
    },
    [1702649] = {
        id = 1702649,
        text = "午飯？你自己隨便解決一下吧。我？我會好好吃的啦，吵死了……",
        minipack = 0,
    },
    [1702650] = {
        id = 1702650,
        text = "辛苦了。我煮了咖啡，你也要來一杯嗎？",
        minipack = 0,
    },
    [1702651] = {
        id = 1702651,
        text = "哈欠……已經這個時間了嗎。嗯，這邊馬上就結束了。你先休息吧。",
        minipack = 0,
    },
    [1702652] = {
        id = 1702652,
        text = "早上好啊，兄長大人。",
        minipack = 0,
    },
    [1702653] = {
        id = 1702653,
        text = "今天下午有模擬戰哦，我會第一個完成的。",
        minipack = 0,
    },
    [1702654] = {
        id = 1702654,
        text = "嘿嘿，今天還過得愉快麼？兄長大人",
        minipack = 0,
    },
    [1702655] = {
        id = 1702655,
        text = "哥哥還沒睡嗎？已經很晚了啊。",
        minipack = 0,
