    [1702656] = {
        id = 1702656,
        text = "嗯……什麼……早上？……別來打擾吾的安睡……退下……吧",
        minipack = 0,
    },
    [1702657] = {
        id = 1702657,
        text = "庫庫，回來了麼，在異界的戰場又有了什麼收穫？",
        minipack = 0,
    },
    [1702658] = {
