    [1702661] = {
        id = 1702661,
        text = "確認。現在進入休息時間。",
        minipack = 0,
    },
    [1702662] = {
        id = 1702662,
        text = "歡迎。今晚已經安排好了。",
        minipack = 0,
    },
    [1702663] = {
