    [10221156] = {
        id = 10221156,
        text = "[光暈]暴擊傷害提升3%。",
        minipack = 0,
    },
    [10221164] = {
        id = 10221164,
        text = "[光暈]在把敵人聚到一起後，會在中間形成能量光柱，產生持續傷害。技能總共可造成折紙攻擊力520%的神聖傷害。",
