    [10221172] = {
        id = 10221172,
        text = "[光暈]暴擊率提升2%。",
        minipack = 0,
    },
    [10221180] = {
        id = 10221180,
        text = "[日輪]光之羽片會在地面殘留一段時間後爆炸。技能總共可造成折紙攻擊力700%的神聖傷害。",
        minipack = 0,
    },
    [10221188] = {
        id = 10221188,
        text = "[日輪]在空中把光之羽片聚集，然後向下刺出爆炸。技能總共可造成折紙攻擊力900%的神聖傷害。",
