        minipack = 0,
    },
    [15011381] = {
        id = 15011381,
        text = "\n\n1.活動期間，誓約者每日進行登入後都可領取一次每日幸運禮包，當每日幸運禮包全服領取次數達到5萬，10萬,15萬時可分別領取一次獎勵",
