    [1705387] = {
        id = 1705387,
        text = "[活動]戰機少女第二彈",
        minipack = 0,
    },
    [15011567] = {
        id = 15011567,
        text = "1.月亮塔活動介紹：\n\n1.連燈成輝:周年慶期間簽到可領取大量好禮！\n\n2.燃月之影:完成周年慶專屬任務，獲得月餅、通寶等。\n\n3.月下小店:周年慶專屬質點以及專屬看板均可在此處使用月餅兌換。其他道具誓約者也可多多查看哦！\n\n4.通寶小鋪:使用中華街貨幣-通寶，可在此處兌換周年慶專屬質點！",
        minipack = 0,
    },
