    [13313387] = {
        id = 13313387,
        text = "每當夜晚降臨，獨特的天賦都能讓大食貓族戰鬥力大大提升。",
        minipack = 0,
    },
    [1000501] = {
        id = 1000501,
        text = "今天該乾些什麼事呢？誒..歡迎光臨...！",
        minipack = 0,
    },
    [13313385] = {
        id = 13313385,
        text = "在惡劣的冰天雪地中生存沒有堅韌的意志可不行。",
        minipack = 0,
    },
    [13313383] = {
        id = 13313383,
        text = "冰天雪地中生活的大食貓族，為瞭解決食物短缺的問題，發明能夠提高產量的黑科技。",
        minipack = 0,
    },
    [13313382] = {
        id = 13313382,
        text = "每一名大食貓族戰士都是一名合格的廚師，戰鬥技巧可以從烹飪中領悟。",
        minipack = 0,
    },
    [13313381] = {
        id = 13313381,
        text = "擁有一條讓人羡慕的毛絨絨尾巴，能夠提升大食貓族的自信，也會在戰鬥中提升士氣。",
        minipack = 0,
    },
    [13313379] = {
        id = 13313379,
        text = "強大的生存能力，是一位合格大食貓族人應該具備的基礎素質。",
        minipack = 0,
    },
    [13313378] = {
        id = 13313378,
        text = "大食貓族是充滿正義感的夥伴，冒險精神驅使她們喜歡幫助弱者。",
        minipack = 0,
    },
    [13313377] = {
        id = 13313377,
        text = "身手敏捷的大食貓族戰士能夠迅速對敵人施展爪痕攻擊。",
        minipack = 0,
    },
    [13313375] = {
        id = 13313375,
        text = "身體柔軟的大食貓族走路可以不發出任何聲音，並快速接近敵人。",
        minipack = 0,
    },
    [13313373] = {
        id = 13313373,
        text = "被上天眷顧的米索不達亞子民往往擁有超凡的運氣。",
        minipack = 0,
    },
    [13313371] = {
        id = 13313371,
        text = "大部分地區被冰雪覆蓋的米索不達亞，是對生存的異常考驗。",
        minipack = 0,
    },
    [13313370] = {
        id = 13313370,
        text = "面對惡劣的自然環境，大食貓族常常將自己的居所改造得更有攻擊性。",
        minipack = 0,
    },
    [13313369] = {
        id = 13313369,
        text = "大食貓族對於一切事物都充滿了好奇，有著一顆研究之心。",
        minipack = 0,
    },
    [13313367] = {
        id = 13313367,
        text = "犬神族人天生就是最值得信賴的夥伴，在戰鬥中犧牲自己為夥伴抵擋傷害。",
        minipack = 0,
    },
    [13313365] = {
        id = 13313365,
        text = "通過奔跑、游泳、舉重，根達亞的子民不斷追求更強的體魄。",
        minipack = 0,
    },
    [13313363] = {
        id = 13313363,
        text = "像野獸一般激發自身的某種戰鬥天賦，獲得意想不到的突破。",
        minipack = 0,
    },
    [13313362] = {
        id = 13313362,
        text = "根達亞子民能夠通過第三只神眼溝通神明，得到神明的恩賜。",
        minipack = 0,
    },
    [13313359] = {
        id = 13313359,
        text = "黑犬部落的強大種族天賦，習得後能夠大幅提升戰鬥屬性。",
        minipack = 0,
    },
    [13313357] = {
        id = 13313357,
        text = "灰犬部落的強大種族天賦，習得後能夠大幅提升戰鬥屬性。",
        minipack = 0,
    },
    [13313355] = {
        id = 13313355,
        text = "天生強大的嗅覺，使得犬神族人擁有敏銳的戰鬥感知。",
        minipack = 0,
    },
    [312002] = {
        id = 312002,
        text = "二、「競速模式」中沒有跳層機制，每層都需要手動挑戰",
        minipack = 0,
    },
    [13313353] = {
