    [2108007] = {
        id = 2108007,
        text = "一、模擬試煉是限時體驗活動，請大家注意時間哦！",
        minipack = 0,
    },
    [2108009] = {
        id = 2108009,
        text = "3.本次模擬試煉主角為白井黑子，請大家盡情享用。",
        minipack = 0,
    },
    [2108011] = {
        id = 2108011,
        text = "您確定要進入該精靈的體驗模式嗎？",
        minipack = 0,
    },
    [2108013] = {
        id = 2108013,
        text = "模擬試煉：陣地",
        minipack = 0,
    },
    [2108015] = {
        id = 2108015,
        text = "遊擊戰的特點是突入敵陣，利用小規模的戰鬥擾亂敵人的陣線。請善加利用單兵作戰的優勢。",
        minipack = 0,
    },
    [2108017] = {
        id = 2108017,
        text = "特攻作戰是針對特定目標進行定點打擊的作戰，高效而精確是其特點。請速戰速決吧。",
        minipack = 0,
    },
    [2108019] = {
        id = 2108019,
        text = "番外：迷惘",
        minipack = 0,
    },
    [2108021] = {
        id = 2108021,
        text = "即是偶然，也是必然。十香的靈裝突然顯現出不尋常的形態，究竟有什麼在前方等待著呢？",
        minipack = 0,
    },
    [2108023] = {
        id = 2108023,
        text = "直面內心，劍鋒相交。在面對過去的自己時，總會有所畏懼。但也正因如此，尋路之人才會有所成長。",
        minipack = 0,
    },
    [2108025] = {
        id = 2108025,
        text = "密謀",
        minipack = 0,
    },
    [2108027] = {
        id = 2108027,
        text = "莫名的敵襲步步緊逼，萬由里也投入了戰鬥當中。初識這個世界的萬由里，會如何看待人類的另一面呢？",
        minipack = 0,
    },
    [2108029] = {
        id = 2108029,
        text = "躲藏在暗處的敵人紛紛現身，金色的光翼淩然展開。陷阱 vs 勇氣，誰會更勝一籌？",
        minipack = 0,
